changeSet.sql:
ALTER TABLE whiteboard.whiteboard_snapshot_asset_manifest
    ADD CONSTRAINT whiteboard_snapshot_asset_manifest_digest_ck CHECK (state_digest ~ '^sha256:[0-9a-f]{64}$'),
    ADD CONSTRAINT whiteboard_snapshot_asset_manifest_extractor_ck CHECK (length(extractor_version) BETWEEN 1 AND 128);

CREATE FUNCTION whiteboard.enforce_asset_upload_transition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.id,NEW.page_id,NEW.actor_id,NEW.idempotency_key,NEW.request_hash,NEW.expected_hash,NEW.content_type,NEW.byte_length,NEW.created_at,NEW.expires_at)
        IS DISTINCT FROM (OLD.id,OLD.page_id,OLD.actor_id,OLD.idempotency_key,OLD.request_hash,OLD.expected_hash,OLD.content_type,OLD.byte_length,OLD.created_at,OLD.expires_at) THEN
        RAISE EXCEPTION 'whiteboard asset upload identity is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state <> OLD.state AND NOT (
        (OLD.state='prepared' AND NEW.state IN ('staging','cancelled','expired')) OR
        (OLD.state='staging' AND NEW.state IN ('prepared','staged','cancelled','expired')) OR
        (OLD.state='staged' AND NEW.state IN ('committed','cancelled','expired'))
    ) THEN
        RAISE EXCEPTION 'invalid whiteboard asset upload transition' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER whiteboard_asset_upload_transition BEFORE UPDATE ON whiteboard.whiteboard_asset_upload
    FOR EACH ROW EXECUTE FUNCTION whiteboard.enforce_asset_upload_transition();
CREATE FUNCTION whiteboard.enforce_asset_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'whiteboard asset content is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER whiteboard_asset_immutable BEFORE UPDATE ON whiteboard.whiteboard_asset
    FOR EACH ROW EXECUTE FUNCTION whiteboard.enforce_asset_immutable();

rollback.sql:
DROP TRIGGER whiteboard_asset_immutable ON whiteboard.whiteboard_asset;
DROP FUNCTION whiteboard.enforce_asset_immutable();
DROP TRIGGER whiteboard_asset_upload_transition ON whiteboard.whiteboard_asset_upload;
DROP FUNCTION whiteboard.enforce_asset_upload_transition();
